package net.officefloor.hq.app.rate;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import net.officefloor.hq.app.sheet.AsOfFilter;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The rates a sheet works out what is due from: its own, then its parent's, then the parent's parent,
 * up to {@link #LEVELS} levels up. A grade with no rate in force on a date on a sheet takes the
 * rate in force for it on that date on the nearest ancestor that has one.
 */
@Service
public class RateChain {

    /** How many levels up a sheet's ancestors' rates are looked for. */
    public static final int LEVELS = 3;

    private final SheetRepository sheets;
    private final RateRepository rates;
    private final RateLogRepository rateLog;

    public RateChain(SheetRepository sheets, RateRepository rates, RateLogRepository rateLog) {
        this.sheets = sheets;
        this.rates = rates;
        this.rateLog = rateLog;
    }

    /** The sheet's id, then its parent's, and so on, up to {@link #LEVELS} levels up. */
    public List<String> lineage(String sheetId) {
        List<String> ids = new ArrayList<>();
        ids.add(sheetId);
        String at = sheetId;
        while (ids.size() <= LEVELS) {
            String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
            if (parent == null || ids.contains(parent)) {
                break;
            }
            ids.add(parent);
            at = parent;
        }
        return ids;
    }

    /** Whether naming {@code parentId} as the sheet's parent would make the sheet its own ancestor. */
    public boolean wouldLoop(String sheetId, String parentId) {
        List<String> seen = new ArrayList<>();
        String at = parentId;
        while (at != null && !seen.contains(at)) {
            if (at.equals(sheetId)) {
                return true;
            }
            seen.add(at);
            at = sheets.findById(at).map(Sheet::getParentId).orElse(null);
        }
        return false;
    }

    /**
     * The rates of the sheet and of each ancestor, nearest first, as the store holds them now. When the
     * request is answered as of a date, only the sheet is restored as it stood then (see {@link AsOfFilter}),
     * so each ancestor's rates are those it had at the end of that date.
     */
    public List<List<Rate>> current(String sheetId) {
        Optional<LocalDate> asOf = AsOfFilter.current();
        List<String> ids = lineage(sheetId);
        List<List<Rate>> chain = new ArrayList<>();
        chain.add(rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId));
        for (String id : ids.subList(1, ids.size())) {
            chain.add(asOf.isPresent() ? rateLog.asOf(id, asOf.get()) : rates.findBySheetIdOrderByGradeAscFromDateAsc(id));
        }
        return chain;
    }

    /** The rates of the sheet and of each ancestor, nearest first, as they stood at the end of a day. */
    public List<List<Rate>> asOf(String sheetId, LocalDate day) {
        return lineage(sheetId).stream().map(id -> rateLog.asOf(id, day)).toList();
    }

    /**
     * The grade's rate in force on a date: the sheet's own (as {@link RateRepository#inForce} picks it),
     * else the nearest ancestor's; empty when none has one.
     */
    public static Optional<Rate> inForce(List<List<Rate>> chain, String grade, LocalDate date) {
        for (List<Rate> level : chain) {
            Optional<Rate> rate = RateRepository.inForce(level, grade, date);
            if (rate.isPresent()) {
                return rate;
            }
        }
        return Optional.empty();
    }

    /** The grade's rate in force on a date on the sheet or, failing that, its nearest ancestor. */
    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
        return inForce(current(sheetId), grade, date);
    }
}
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.stream.IntStream;
import net.officefloor.hq.app.claim.ClaimService;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/**
 * Listing and setting the sheet's rates for each grade, each from an optional from-date and through
 * an optional to-date.
 */
@RestController
@RequestMapping("/api/rates")
public class RateController {

    /** A percent: 0.00 to 999.99, with up to two decimals. */
    private static final String PCT = "\\d{1,3}(\\.\\d{1,2})?";

    public record ListRatesRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    public record SetRateRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull @Pattern(regexp = "[ABC]") String grade, @NotNull @Pattern(regexp = PCT) String pct,
            LocalDate from, LocalDate to) {
    }

    public record ImportRatesRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull @Size(max = 100000) String text) {
    }

    /** What an import set: how many rates, and each one set, in line order. */
    public record ImportRatesResponse(int set, List<RateResponse> rates) {
    }

    public record PreviewRateRequest(@NotBlank @Size(max = 100) String sheet,
            @NotNull @Pattern(regexp = "[ABC]") String grade, @NotNull @Pattern(regexp = PCT) String pct) {
    }

    public record PreviewRateResponse(int count, String diff) {
    }

    /** A rate; {@code level} 0 for the sheet's own, 1 for its parent's, 2 for the parent's parent, and so on. */
    public record RateResponse(String grade, LocalDate from, LocalDate to, String pct, int level) {
    }

    private static RateResponse response(Rate rate, int level) {
        return new RateResponse(rate.getGrade(), rate.getFromDate(), rate.getToDate(),
                rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString(), level);
    }

    private final RateService service;
    private final RateImportService imports;
    private final ClaimService claims;

    public RateController(RateService service, RateImportService imports, ClaimService claims) {
        this.service = service;
        this.imports = imports;
        this.claims = claims;
    }

    /** The sheet's own rates, then those of each of its ancestors (see {@link RateChain}), each with its level. */
    @PostMapping("/list")
    public List<RateResponse> list(@Valid @RequestBody ListRatesRequest req) {
        List<List<Rate>> levels = service.list(req.sheet().trim());
        return IntStream.range(0, levels.size())
                .boxed().flatMap(level -> levels.get(level).stream().map(rate -> response(rate, level))).toList();
    }

    /** How many OPEN and PENDING claims a candidate rate for a grade would change, and by how much in all. Saves nothing. */
    @PostMapping("/preview")
    public PreviewRateResponse preview(@Valid @RequestBody PreviewRateRequest req) {
        ClaimService.RatePreview preview = claims.previewRate(req.sheet().trim(), req.grade(),
                new BigDecimal(req.pct()).setScale(2, RoundingMode.UNNECESSARY));
        return new PreviewRateResponse(preview.count(), preview.diff().toPlainString());
    }

    @PostMapping("/set")
    public RateResponse set(@Valid @RequestBody SetRateRequest req) {
        return response(service.set(req.sheet().trim(), req.user().trim(), req.grade(), req.from(), req.to(),
                new BigDecimal(req.pct()).setScale(2, RoundingMode.UNNECESSARY)), 0);
    }

    @PostMapping("/import")
    public ImportRatesResponse importRates(@Valid @RequestBody ImportRatesRequest req) {
        List<Rate> set = imports.importRates(req.sheet().trim(), req.user().trim(), req.text());
        return new ImportRatesResponse(set.size(), set.stream().map(rate -> response(rate, 0)).toList());
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.role.RoleService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The rate import box: lines of {@code grade,rate,from,to}, taken in order (from and to may be absent
 * or blank). Every line is held to the rate form's rules before anything is set; then each is set
 * exactly as the rate form sets it, replacing a rate for the same grade and from-date. The import is
 * one change, so a refused line sets nothing and writes nothing. Blank lines are skipped; an import
 * with no lines is refused.
 */
@Service
public class RateImportService {

    /** A percent: 0.00 to 999.99, with up to two decimals. */
    private static final String PCT = "\\d{1,3}(\\.\\d{1,2})?";

    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
    }

    private final RateService rates;
    private final RoleService roles;

    public RateImportService(RateService rates, RoleService roles) {
        this.rates = rates;
        this.roles = roles;
    }

    /** Sets every line's rate in order: the rates set, in line order. */
    @Transactional
    public List<Rate> importRates(String sheetId, String user, String text) {
        roles.refuseViewer(sheetId, user);
        List<Line> lines = new ArrayList<>();
        String[] raw = text.split("\\r?\\n|\\r");
        for (int i = 0; i < raw.length; i++) {
            if (!raw[i].isBlank()) {
                lines.add(parse(i + 1, raw[i]));
            }
        }
        if (lines.isEmpty()) {
            throw refused("Paste at least one line of grade,rate,from,to.");
        }
        List<Rate> set = new ArrayList<>();
        for (Line line : lines) {
            set.add(rates.set(sheetId, user, line.grade(), line.from(), line.to(), line.pct()));
        }
        return set;
    }

    private static Line parse(int number, String text) {
        String[] fields = text.split(",", -1);
        if (fields.length < 2 || fields.length > 4) {
            throw refused("Line " + number + " needs a grade and a rate, then optionally a from-date and a to-date.");
        }
        String grade = fields[0].trim();
        if (!grade.matches("[ABC]")) {
            throw refused("Line " + number + ": choose a grade of A, B or C.");
        }
        String pct = fields[1].trim();
        if (!pct.matches(PCT)) {
            throw refused("Line " + number + ": enter a rate from 0.00 to 999.99, with up to two decimals.");
        }
        LocalDate from = date(number, fields.length > 2 ? fields[2] : "", "from-date");
        LocalDate to = date(number, fields.length > 3 ? fields[3] : "", "to-date");
        if (from != null && to != null && to.isBefore(from)) {
            throw refused("Line " + number + ": the to-date cannot be before the from-date.");
        }
        return new Line(grade, new BigDecimal(pct).setScale(2, RoundingMode.UNNECESSARY), from, to);
    }

    private static LocalDate date(int number, String field, String what) {
        String text = field.trim();
        if (text.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw refused("Line " + number + ": enter the " + what + " as yyyy-mm-dd, or leave it blank.");
        }
    }

    private static ResponseStatusException refused(String reason) {
        return new ResponseStatusException(HttpStatus.BAD_REQUEST, reason);
    }
}
