                Map.of("SHEET_ID", onClone, "PERSON_ID", person, "PATRON_ID", person));

        copy("PERIOD", "sheet_id = ?", sheetId, "ORDER BY id", Map.of("SHEET_ID", onClone, "CLOSED", v -> false,
                "SOFT_CLOSED", v -> false, "CLOSED_DUE", v -> null, "LAST_CLAIM_NUMBER", v -> 0));

